function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var LABEL        = settings.label.value;          // caption in the strip at the bottom ('' = no strip)
  var MULTIPLIER   = settings.multiplier.value;     // value * multiplier (km/h -> kts = 0.539957, m/s -> kts = 1.94384, m -> ft = 3.28084, 1 = as is)
  var DIGITS       = settings.digits.value;         // decimal places of the value in the box (0 for a split value)
  var SMALL_DIGITS = settings.small_digits.value;   // how many trailing digits of the value are printed smaller (Airbus altitude: 3 -> "32 300"; 0 = none)
  var SMOOTH_MS    = settings.smooth_ms.value;      // moving average window for the value in ms (0 = off)
  var CLAMP_ZERO   = settings.clamp_zero.value;     // do not draw the scale below zero (speed tapes)
  var SPAN         = settings.visible_span.value;   // units visible from the top to the bottom of the tape
  var MAJOR        = settings.number_step.value;    // units between two scale numbers (long ticks)
  var MINOR        = settings.minor_ticks.value;    // short ticks between two numbers (0 = none)
  var TICK_SIDE    = settings.tick_side.value;      // 'right' (Airbus speed tape) | 'left' (Airbus altitude tape)
  var NUM_DIGITS   = settings.number_digits.value;  // decimal places of the scale numbers
  var PANEL_COLOR  = settings.panel_color.value;    // translucent tape background
  var LINE_COLOR   = settings.line_color.value;     // reference line through the value box
  var BOX_COLOR    = settings.box_color.value;      // value box background
  var BOX_BORDER   = settings.box_border.value;     // value box border color
  var STRIP_COLOR  = settings.strip_color.value;    // caption strip background
  var TEXT_COLOR   = settings.text_color.value;     // value color
  var NUM_COLOR    = settings.number_color.value;   // scale numbers and ticks
  var LABEL_COLOR  = settings.label_color.value;    // caption color
  var FONT         = settings.font.value;           // font family
  var VALUE_SIZE   = settings.value_size.value;     // value font size at the default 130x410 size; scales with the widget
  var SMALL_SIZE   = settings.small_size.value;     // font size of the smaller trailing digits at the default size; scales with the widget
  var NUM_SIZE     = settings.number_size.value;    // scale numbers font size at the default size; scales with the widget
  var LABEL_SIZE   = settings.label_size.value;     // caption font size at the default size; scales with the widget
  var SHADOW       = settings.text_shadow.value;    // CSS text shadow for all texts ('' = none)
  var RADIUS       = settings.radius.value;         // panel corner radius at the default size; scales with the widget
  var OPACITY      = settings.opacity.value;        // whole-widget opacity 0..1 (1 = opaque)
  // -------------------------------
  var W = ctx.width, H = ctx.height, s = ctx.state, i;
  var scale = Math.min(W / 130, H / 410);
  var col = ctx.columns[0];
  var RIGHT = TICK_SIDE !== 'left';

  // ---- value (smoothed when asked; only inside the telemetry range) ----
  var raw = ctx.values[0], cur;
  if (typeof raw === 'number') {
    if (SMOOTH_MS > 0 && col) {
      var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 400) || [], sum = 0, cnt = 0;
      for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
      cur = cnt ? sum / cnt : raw;
    } else cur = raw;
    cur *= MULTIPLIER;
  }

  // ---- geometry ----
  var fs = VALUE_SIZE * scale, sfs = SMALL_SIZE * scale, nfs = NUM_SIZE * scale, lfs = LABEL_SIZE * scale;
  var sw = 2 * scale;                                  // border / tick stroke
  var tickL = 10 * scale, tickS = 5 * scale, tc = tickL + 3 * scale;   // tick column width
  var stripH = LABEL ? lfs * 1.7 : 0;
  var tapeH = H - stripH, cy = tapeH / 2;
  var notch = fs * 0.28, bh = fs * 1.35, pad = 4 * scale;
  var bx0 = RIGHT ? pad : tc + notch + 2 * scale, bx1 = RIGHT ? W - tc - notch - 2 * scale : W - pad;
  var tickX = RIGHT ? W : 0, dir = RIGHT ? -1 : 1;    // ticks grow inwards from the edge
  var numX = RIGHT ? W - tc - 3 * scale : tc + 3 * scale, anchor = RIGHT ? 'end' : 'start';
  var shadow = SHADOW ? ' style="text-shadow:' + SHADOW + '"' : '';
  var uid = (s.uid || (s.uid = 'u' + Math.random().toString(36).slice(2, 8))) + (s.frame = ((s.frame || 0) + 1) % 1000000);

  // ---- static part: panel, caption strip, value box (built once per size / look) ----
  var staticKey = W + 'x' + H + '|' + TICK_SIDE + '|' + PANEL_COLOR + '|' + STRIP_COLOR + '|' + BOX_COLOR + '|' + BOX_BORDER + '|' + LABEL + '|' + LABEL_COLOR + '|' + fs + '|' + lfs + '|' + RADIUS + '|' + SHADOW;
  if (s.staticKey !== staticKey) {
    var r = (RADIUS * scale).toFixed(1);
    var sv = '<rect x="0" y="0" width="' + W + '" height="' + tapeH.toFixed(2) + '" rx="' + r + '" fill="' + PANEL_COLOR + '"/>';
    if (LABEL) {
      // caption strip: the bottom corner on the tick side is cut off (speed tape: right, altitude tape: left)
      var slant = stripH * 0.45, top = (tapeH + 1.5 * scale).toFixed(2);
      sv += '<path d="M0,' + top + ' L' + W + ',' + top + (RIGHT ? ' L' + (W - slant).toFixed(2) + ',' + H + ' L0,' + H : ' L' + W + ',' + H + ' L' + slant.toFixed(2) + ',' + H) + ' Z" fill="' + STRIP_COLOR + '"/>'
        + '<text x="' + ((RIGHT ? W - slant : W + slant) / 2).toFixed(2) + '" y="' + (tapeH + stripH * 0.55).toFixed(2) + '" fill="' + LABEL_COLOR + '" font-size="' + lfs.toFixed(1) + '" font-weight="bold" letter-spacing="' + (1 * scale).toFixed(1) + '" text-anchor="middle" dominant-baseline="central"' + shadow + '>' + LABEL + '</text>';
    }
    // value box with a pointer notch towards the ticks
    var y0 = (cy - bh / 2).toFixed(2), y1 = (cy + bh / 2).toFixed(2), tip = RIGHT ? (bx1 + notch).toFixed(2) : (bx0 - notch).toFixed(2);
    var box = RIGHT
      ? 'M' + bx0.toFixed(2) + ',' + y0 + ' L' + bx1.toFixed(2) + ',' + y0 + ' L' + bx1.toFixed(2) + ',' + (cy - notch).toFixed(2) + ' L' + tip + ',' + cy.toFixed(2) + ' L' + bx1.toFixed(2) + ',' + (cy + notch).toFixed(2) + ' L' + bx1.toFixed(2) + ',' + y1 + ' L' + bx0.toFixed(2) + ',' + y1 + ' Z'
      : 'M' + bx1.toFixed(2) + ',' + y0 + ' L' + bx0.toFixed(2) + ',' + y0 + ' L' + bx0.toFixed(2) + ',' + (cy - notch).toFixed(2) + ' L' + tip + ',' + cy.toFixed(2) + ' L' + bx0.toFixed(2) + ',' + (cy + notch).toFixed(2) + ' L' + bx0.toFixed(2) + ',' + y1 + ' L' + bx1.toFixed(2) + ',' + y1 + ' Z';
    s.boxSvg = '<path d="' + box + '" fill="' + BOX_COLOR + '" stroke="' + BOX_BORDER + '" stroke-width="' + sw.toFixed(2) + '" stroke-linejoin="round"/>';
    s.staticSvg = sv; s.staticKey = staticKey;
  }

  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="display:block;font-family:' + FONT + ';opacity:' + OPACITY + '">' + s.staticSvg;

  // ---- moving scale: ticks + numbers, clipped to the tape ----
  if (typeof cur === 'number' && SPAN > 0 && MAJOR > 0) {
    var ppu = tapeH / SPAN, minor = Math.max(0, Math.round(MINOR)) + 1, tick = MAJOR / minor;
    var vLo = cur - SPAN / 2 - MAJOR, vHi = cur + SPAN / 2 + MAJOR;
    if (CLAMP_ZERO && vLo < 0) vLo = 0;
    var k0 = Math.ceil(vLo / tick - 1e-9), k1 = Math.floor(vHi / tick + 1e-9);
    if (k1 - k0 > 400) k1 = k0 + 400;                  // guard against a silly span / step combination
    out += '<defs><clipPath id="' + uid + '"><rect x="0" y="0" width="' + W + '" height="' + tapeH.toFixed(2) + '"/></clipPath></defs><g clip-path="url(#' + uid + ')">';
    for (i = k0; i <= k1; i++) {
      var v = i * tick, y = cy - (v - cur) * ppu, isMajor = (i % minor === 0);
      var len = isMajor ? tickL : tickS;
      out += '<line x1="' + tickX + '" y1="' + y.toFixed(2) + '" x2="' + (tickX + dir * len).toFixed(2) + '" y2="' + y.toFixed(2) + '" stroke="' + NUM_COLOR + '" stroke-width="' + (isMajor ? sw : sw * 0.7).toFixed(2) + '"/>';
      if (isMajor && Math.abs(y - cy) > bh / 2 + nfs * 0.45) {   // numbers under the value box are hidden by it (Airbus does the same)
        var nv = Math.round(v / MAJOR) * MAJOR;          // kills float noise (0.30000000004)
        out += '<text x="' + numX.toFixed(2) + '" y="' + y.toFixed(2) + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" font-weight="bold" text-anchor="' + anchor + '" dominant-baseline="central"' + shadow + '>' + nv.toFixed(NUM_DIGITS) + '</text>';
      }
    }
    out += '</g>';
  }

  // ---- reference line, value box, value ----
  out += '<line x1="0" y1="' + cy.toFixed(2) + '" x2="' + W + '" y2="' + cy.toFixed(2) + '" stroke="' + LINE_COLOR + '" stroke-width="' + sw.toFixed(2) + '"/>' + s.boxSvg;
  var bigStr = '--', smallStr = '';
  if (typeof cur === 'number') {
    if (SMALL_DIGITS > 0) {
      var neg = cur < 0, iv = Math.round(Math.abs(cur)), pow = Math.pow(10, SMALL_DIGITS), hi = Math.floor(iv / pow), lo = iv % pow;
      if (hi > 0) { bigStr = (neg ? '-' : '') + hi; smallStr = String(lo); while (smallStr.length < SMALL_DIGITS) smallStr = '0' + smallStr; }
      else bigStr = (neg ? '-' : '') + lo;
    } else bigStr = cur.toFixed(DIGITS);
  }
  var by = (cy + fs * 0.36).toFixed(2), bcx = (bx0 + bx1) / 2;
  if (smallStr) {
    // both parts share one baseline; the pair is centred in the box by an estimated width
    var wBig = bigStr.length * fs * 0.6, wSmall = smallStr.length * sfs * 0.6, x0 = bcx - (wBig + wSmall) / 2;
    out += '<text x="' + x0.toFixed(2) + '" y="' + by + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold"' + shadow + '>' + bigStr
      + '<tspan font-size="' + sfs.toFixed(1) + '" dx="' + (fs * 0.05).toFixed(1) + '">' + smallStr + '</tspan></text>';
  } else {
    out += '<text x="' + bcx.toFixed(2) + '" y="' + by + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" text-anchor="middle"' + shadow + '>' + bigStr + '</text>';
  }
  out += '</svg>';
  return out;
}
